public class RequestContextHolder {
    private static final ThreadLocal<String> USER_ID = new ThreadLocal<>();

    public static void setUserId(String id) { USER_ID.set(id); }

    public static String getUserId() { return USER_ID.get(); }

    public static void clear() { USER_ID.remove(); } // CRITICAL: Prevent memory leaks
}

// Usage in a Filter or Interceptor
try {
    RequestContextHolder.setUserId(request.getHeader("X-User-ID"));
    chain.doFilter(request, response);
} finally {
    RequestContextHolder.clear(); // Always clean up in finally block
}
